import {localize,tr} from './ko.js';
let data,view='scanner',tab='All research',query='',themeFilter='',sortKey='score',sortDir=-1;
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label='Source')=>/^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'DATA UNAVAILABLE';
const na='<span class="na">DATA UNAVAILABLE</span>';
const fmt=(v,unit='')=>v==null||!Number.isFinite(v)?na:unit==='USD'?`$${Math.abs(v)>=1e9?(v/1e9).toFixed(2)+'B':Math.abs(v)>=1e6?(v/1e6).toFixed(1)+'M':v.toFixed(2)}`:`${v.toFixed(1)}${unit}`;
const v=(c,k)=>c.metrics?.[k]?.value;
let watch=[];try{watch=JSON.parse(localStorage.getItem('nbs-watch')||'[]');if(!Array.isArray(watch))watch=[];}catch{}
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const notice=text=>$('#notice').innerHTML=text?`<div class="notice">${esc(text)}</div>`:'';
async function api(path,body){const r=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!r.ok){let err;try{err=await r.json();}catch{}throw Error(err?.error||'Request failed');}return r.json();}
async function load(){try{data=await api('snapshot');watch=data.watchlist;}catch{const r=await fetch('snapshot.json');if(!r.ok)throw Error('Snapshot unavailable');data=await r.json();}$('#mode').innerHTML=data.mode==='local'?'LOCAL ENGINE':'SNAPSHOT VIEWER';$('#date').textContent=new Date(data.generatedAt).toLocaleDateString('ko-KR',{year:'numeric',month:'short',day:'2-digit'});$('#refresh').textContent=data.mode==='local'?'↻ Update research':'↻ Reload snapshot';render();}
const core=()=>data.companies.filter(c=>c.assessment.eligible);
function stats(){return `<div class="stats"><div class="stat"><label>RESEARCH UNIVERSE</label><strong>${String(data.companies.length).padStart(2,'0')}</strong><small>investigation seeds</small></div><div class="stat"><label>VERIFIED CANDIDATES</label><strong style="color:var(--accent)">${String(core().length).padStart(2,'0')}</strong><small>eligibility passed</small></div><div class="stat"><label>BOTTLENECK HYPOTHESES</label><strong>${String(data.themes.length).padStart(2,'0')}</strong><small>causal chains</small></div><div class="stat"><label>AWAITING CHINA REVIEW</label><strong>${String(data.companies.filter(c=>!c.assessment.chinaRisk).length).padStart(2,'0')}</strong><small>excluded from core</small></div></div>`;}
function cards(){return `<div class="cards">${data.themes.map((t,i)=>`<button class="bottleneck ${themeFilter===t.id?'selected':''}" data-theme="${esc(t.id)}"><span class="index">0${i+1} / ${esc(t.category)}</span><span class="arrow">↗</span><h3>${esc(t.title)}</h3><div class="bottom"><span>${data.companies.filter(c=>c.themes.includes(t.id)).length} research leads</span><span>HYPOTHESIS</span></div></button>`).join('')}</div>`;}
const tabs=['All research','New Discoveries','Thesis Strengthening','Thesis Weakening','Too Expensive / Too Late','China Risk Excluded','Watchlist'];
function filterRows(){return data.companies.filter(c=>(!query||`${c.ticker} ${c.name}`.toLowerCase().includes(query.toLowerCase()))&&(!themeFilter||c.themes.includes(themeFilter))&&(tab==='All research'||tab==='New Discoveries'&&c.discovery==='New Discoveries'||tab===c.change||tab==='Too Expensive / Too Late'&&c.assessment.status==='Fully Priced'||tab==='China Risk Excluded'&&c.assessment.chinaRisk==='HIGH'||tab==='Watchlist'&&watch.includes(c.ticker))).sort((a,b)=>{const key=c=>sortKey==='score'?c.assessment.score:sortKey==='ticker'?c.ticker:sortKey==='chinaRisk'?c.assessment.chinaRisk:sortKey==='performance52'?c.technical?.performance52:v(c,sortKey);const aa=key(a),bb=key(b);if(aa==null)return bb==null?0:1;if(bb==null)return -1;return(typeof aa==='string'?aa.localeCompare(bb):aa-bb)*sortDir;});}
function table(){return `<div class="table-wrap"><table><thead><tr><th></th>${[['ticker','COMPANY'],['marketCap','MKT CAP'],['','BOTTLENECK'],['score','SCORE ↓'],['revenueGrowth','REV YoY'],['backlogGrowth','BACKLOG YoY'],['forwardPE','FWD P/E'],['performance52','52W RETURN'],['chinaRisk','CHINA RISK'],['','TECHNICAL SETUP'],['','CATALYST']].map(([key,label])=>`<th>${key?`<button data-sort="${key}">${label}</button>`:label}</th>`).join('')}</tr></thead><tbody>${filterRows().map(c=>`<tr><td><button class="star ${watch.includes(c.ticker)?'on':''}" data-watch="${esc(c.ticker)}" aria-label="${esc(c.ticker)} Watchlist">${watch.includes(c.ticker)?'★':'☆'}</button></td><td><button class="ticker" data-company="${esc(c.ticker)}">${esc(c.ticker)}</button><div class="company-name">${esc(c.name)}</div></td><td class="num">${fmt(v(c,'marketCap'),'USD')}<div class="company-name">${esc(c.assessment.universe)}</div></td><td><span class="company-name">${esc(data.themes.find(t=>c.themes.includes(t.id))?.title||'검토 대기')}</span></td><td class="num">${c.assessment.score??na}<div class="company-name">${c.assessment.coverage}% coverage</div>${c.oldNewGrowth?badge('NEW ENGINE','green'):''}</td><td class="num">${fmt(v(c,'revenueGrowth'),'%')}</td><td class="num">${fmt(v(c,'backlogGrowth'),'%')}</td><td class="num">${fmt(v(c,'forwardPE'),'x')}</td><td class="num">${fmt(c.technical?.performance52,'%')}</td><td>${c.assessment.chinaRisk?badge(c.assessment.chinaRisk,c.assessment.chinaRisk==='HIGH'?'red':c.assessment.chinaRisk==='LOW'?'green':'amber'):badge('REVIEW REQUIRED','amber')}</td><td>${c.assessment.divergence?badge('DIVERGENCE','green'):c.technical?.sma200?badge(c.technical.close>c.technical.sma200?'ABOVE 200D':'BELOW 200D'):na}</td><td>${c.catalysts[0]?esc(c.catalysts[0].eventDate):na}</td></tr>`).join('')||'<tr><td colspan="12" class="empty">조건에 맞는 검증 신호가 없습니다. 후보를 임의로 채우지 않습니다.</td></tr>'}</tbody></table></div>`;}
function scanner(){return `<div class="context"><div class="context-label">THE STRUCTURAL<br>READ-THROUGH</div><p>${esc(data.marketContext)}</p></div>${stats()}<div class="section-head"><h2>TODAY'S EMERGING BOTTLENECKS</h2><small>가설 → 증거 → 기업 변화</small></div>${cards()}<div class="section-head"><h2>HIDDEN MIDCAP CANDIDATES</h2><small>Verified facts. Explicit uncertainty.</small></div><div class="tabs" role="tablist">${tabs.map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}" role="tab" aria-selected="${tab===t}">${t}</button>`).join('')}</div><div class="toolbar"><input id="search" class="search" value="${esc(query)}" placeholder="회사명 또는 티커 검색…" aria-label="회사 검색"><div class="row-actions"><select id="themeFilter" aria-label="병목 필터"><option value="">All bottlenecks</option>${data.themes.map(t=>`<option value="${t.id}" ${themeFilter===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select><button id="exportCsv">↓ Export CSV</button></div></div><div id="results">${table()}</div><div class="footnote">초기 기업은 조사 출발점이며 추천·검증된 중형주 목록이 아닙니다. 결측값은 0으로 대체하지 않습니다. 점수는 충족률 60% 이상에서만 공개됩니다.</div>`;}
function thesis(t){return `<section class="panel"><div class="kicker">${esc(t.category)} · ANALYST HYPOTHESIS</div><h2>${esc(t.title)}</h2><div class="flow">${t.chain.map((n,i)=>`${i?'<span class="flow-arrow">→</span>':''}<div class="node">${esc(n)}</div>`).join('')}</div><div class="grid2"><div><h3>Why it becomes scarce</h3><p class="muted">${esc(t.scarcity)}</p><h3>Approximate timing</h3><p class="muted">${esc(t.timing)}</p></div><div><h3>Counterargument</h3><p class="muted">${esc(t.counter)}</p><h3>What invalidates the thesis</h3><p class="muted">${esc(t.invalidate)}</p></div></div><h3>Companies exposed · verification pending</h3><div class="row-actions">${data.companies.filter(c=>c.themes.includes(t.id)).map(c=>`<button data-company="${c.ticker}">${c.ticker} ↗</button>`).join('')||na}</div><h3>Evidence</h3>${data.companies.filter(c=>c.themes.includes(t.id)).flatMap(c=>c.evidence.filter(e=>e.reviewed).map(e=>`<p>${esc(c.ticker)} — ${esc(e.note)} ${link(e.source)}</p>`)).join('')||'<p class="muted">연결된 검증 증거 없음. 인과관계는 확정된 사실이 아닙니다.</p>'}</section>`;}
function calendar(){const events=data.companies.flatMap(c=>c.catalysts.map(e=>({...e,ticker:c.ticker}))).sort((a,b)=>a.eventDate.localeCompare(b.eventDate));return `<div class="section-head"><h2>CATALYST CALENDAR / NEXT 30 DAYS</h2><button data-add>+ Add confirmed event</button></div><div class="panel">${events.map(e=>`<div class="source-row"><div><span class="kicker">${esc(e.eventDate)}</span><p><button data-company="${e.ticker}">${e.ticker}</button> ${esc(e.note)}</p></div>${link(e.source,'Official announcement')}</div>`).join('')||'<div class="empty">공식 발표로 확인된 향후 30일 이벤트가 없습니다.<br>실적 발표일을 과거 일정으로 추정하지 않습니다.</div>'}</div>`;}
function sources(){return `<div class="section-head"><h2>DATA HEALTH & PROVENANCE</h2><button data-add class="primary">+ Add evidence</button></div><div class="grid2"><section class="panel"><h2>Source hierarchy</h2><div class="source-row"><span>01 · SEC EDGAR</span><span>Financial facts / filings</span></div><div class="source-row"><span>02 · Official IR</span><span>Orders / segments / China</span></div><div class="source-row"><span>03 · Market providers</span><span>Price / valuation</span></div><p class="help">시계열과 문서는 출처·관측일·회계 기간을 보존합니다. 공식 수치와 계산치는 별도로 표시합니다.</p>${link('https://www.sec.gov/search-filings/edgar-application-programming-interfaces','SEC API documentation')}</section><section class="panel"><h2>Collection status</h2><p>${badge(data.mode==='local'?'LOCAL ENGINE':'EXPORTED SNAPSHOT','green')}</p><p class="help">${data.mode==='local'?'업데이트 실행은 SEC·시장 데이터를 수집하고 리포트를 저장합니다.':'이 사이트는 마지막으로 내보낸 데이터입니다. 자동 수집과 증거 저장은 함께 제공된 로컬 엔진에서 실행합니다.'}</p><p class="help">SEC_USER_AGENT · 실제 연락 이메일 필요<br>ALPHA_VANTAGE_API_KEY · 밸류에이션/대체 가격 데이터</p></section></div><section class="panel"><h2>Recent pipeline runs</h2>${data.runs.map(r=>`<div class="evidence"><p>${badge(r.status,r.status==='succeeded'?'green':'amber')} ${esc(r.started)}</p>${(r.payload?.failures||[]).map(f=>`<p class="help">${esc(f.ticker)} · ${esc(f.provider)} · ${esc(f.message)}</p>`).join('')}${r.payload?.message?esc(r.payload.message):''}</div>`).join('')||'<p class="muted">수집 이력이 없습니다. API 설정 후 첫 업데이트를 실행하세요.</p>'}</section><section class="panel"><h2>Document ingestion</h2><p class="help">실적 콜 또는 공식 IR 원문을 넣으면 길이로 정규화한 키워드 빈도를 추적합니다. 동일 종류 문서의 분기별 비교를 권장합니다.</p><form id="documentForm"><div class="form-grid"><label>Ticker<select name="ticker">${data.companies.map(c=>`<option>${c.ticker}</option>`).join('')}</select></label><label>Document kind<select name="kind"><option>earnings-call</option><option>IR</option><option>10-Q</option><option>10-K</option></select></label><label>Period<input type="date" name="period" required></label><label>Official source<input type="url" name="source" required placeholder="https://…"></label></div><label>Document text<textarea name="text" rows="6" required></textarea></label><button class="primary">Analyze document</button></form></section><section class="panel"><h2>Expand research universe</h2><form id="companyForm"><div class="form-grid"><label>Ticker<input name="ticker" required placeholder="TICKER"></label><label>SEC CIK<input name="cik" required placeholder="0000000000"></label></div><label>Company name<input name="name" required></label><button>Add company</button></form><p class="help">전체 미국 거래소 목록 수집: npm run update -- --universe. 기업별 수집은 실행당 설정한 개수로 순환합니다.</p></section>`;}
function render(){if(!data)return;const names={scanner:'Discovery terminal',theses:'Bottleneck engine',calendar:'Catalyst calendar',report:'Daily intelligence',sources:'Data & evidence'};$('#pageLabel').textContent=names[view];document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#app').innerHTML=view==='scanner'?scanner():view==='theses'?`<div class="section-head"><h2>NEXT BOTTLENECK ENGINE</h2><small>3–5 causal transitions</small></div>${data.themes.map(thesis).join('')}<section class="panel"><h2>Emerging theme review queue</h2><p class="muted">${[...(data.proposedThemes||[]),...(data.themeProposals||[]).map(t=>t.phrase+' / '+t.ticker)].length?esc([...(data.proposedThemes||[]),...(data.themeProposals||[]).map(t=>t.phrase+' / '+t.ticker)].join(', ')):'새로운 키워드 급증 신호 없음'}</p></section>`:view==='calendar'?calendar():view==='sources'?sources():`<div class="section-head"><h2>US MIDCAP NEXT BOTTLENECK DAILY</h2><button id="downloadReport">↓ Download report</button></div><div id="reportBody" class="panel report">Generating…</div>`;if(view==='report')renderReport();bind();localize(document.body);}
const metricLabels={marketCap:'Market cap',enterpriseValue:'Enterprise value',revenue:'Quarterly revenue',revenueTTM:'Revenue TTM',revenueGrowth:'Revenue growth YoY',revenueQoQ:'Revenue growth QoQ',epsGrowth:'EPS growth',grossMargin:'Gross margin',operatingMargin:'Operating margin',freeCashFlow:'Free cash flow',netDebt:'Net debt',forwardPE:'Forward P/E',trailingPE:'Trailing P/E',evSales:'EV / Sales',evEbitda:'EV / EBITDA',peg:'PEG',shortInterest:'Short interest',institutionalOwnership:'Institutional ownership',acceleration:'Revenue acceleration',marginChange:'Gross margin change',backlog:'Backlog',backlogGrowth:'Backlog growth',bookings:'Bookings',bookingsGrowth:'Bookings growth',bookToBill:'Book-to-bill',capexGrowth:'Capex growth',dataCenterRevenueGrowth:'Data center revenue growth',aiRevenueGrowth:'AI revenue growth',newProductRevenueGrowth:'New product revenue growth',growthSegmentShare:'Growth segment share',customerConcentrationChange:'Customer concentration change'};
function metric(c,k){const m=c.metrics?.[k];return `<div class="metric"><label>${metricLabels[k]||esc(k)}</label><b>${fmt(m?.value,m?.unit)}</b><small>${m?.value!=null?`${esc(m.kind)} · ${esc(m.period_end||'')}<br>${link(m.source)}`:'No verified observation'}</small></div>`;}
function chart(c){const b=c.bars||[];if(b.length<2)return '<div class="empty">DATA UNAVAILABLE<br>검증된 가격 시계열을 수집하면 차트가 표시됩니다.</div>';const prices=b.slice(-252),min=Math.min(...prices.map(x=>x.close)),max=Math.max(...prices.map(x=>x.close)),d=prices.map((x,i)=>`${i?'L':'M'}${(i/(prices.length-1)*900+20).toFixed(2)},${(220-(x.close-min)/(max-min||1)*190).toFixed(2)}`).join(' ');return `<svg class="chart" viewBox="0 0 940 250" role="img" aria-label="${esc(c.ticker)} price history"><line x1="20" y1="220" x2="920" y2="220" stroke="#32404a"/><path d="${d}"/><text x="20" y="245" fill="#95a4ad" font-size="12">${esc(prices[0].date)}</text><text x="810" y="245" fill="#95a4ad" font-size="12">${esc(prices.at(-1).date)}</text></svg><p class="help">${c.technical.adjusted?'Adjusted price':'Unadjusted · technical scoring disabled'} · ${link(c.technical.source)} · ${esc(c.technical.asOf)}</p>`;}
function openCompany(ticker){const c=data.companies.find(c=>c.ticker===ticker);if(!c)throw Error('Unknown ticker');const a=c.assessment;const notes=key=>c.evidence.filter(e=>e.key===key&&e.reviewed).map(e=>`<p>${esc(e.note)} ${link(e.source)}</p>`).join('')||'<p class="muted">DATA UNAVAILABLE — 검증된 자료 필요</p>';
 $('#detailContent').innerHTML=`<div class="dialog-head"><div><span class="kicker">COMPANY RESEARCH / ${esc(a.universe)}</span><h2>${esc(c.ticker)} <span class="muted">${esc(c.name)}</span></h2></div><button class="close" data-close="detail" aria-label="닫기">×</button></div><p>${badge(a.status,a.status==='Research Priority'?'green':'')} ${badge('Coverage '+a.coverage+'%')} ${badge(a.chinaRisk?'China '+a.chinaRisk:'China review required','amber')}</p><div class="row-actions"><button data-watch="${c.ticker}">${watch.includes(c.ticker)?'★ Watching':'☆ Watch company'}</button><button data-add="${c.ticker}">+ Add evidence</button></div><section class="panel"><h2>Company snapshot</h2><p class="help">${esc(c.exchange||'US exchange verification pending')} · Updated ${esc(c.updatedAt||'Not collected')}</p><div class="metric-grid">${Object.keys(metricLabels).slice(0,18).map(k=>metric(c,k)).join('')}</div></section><div class="grid2"><section class="panel"><h2>Why this company matters</h2>${notes('why')}<h3>Major customers</h3>${notes('customers')}<h3>Competition</h3>${notes('competition')}</section><section class="panel"><h2>Bottleneck score ${a.score??'—'} / 100</h2>${Object.entries(a.points).map(([k,val])=>`<div class="score-row"><span>${k}</span><span>${val==null?'Not assessed':val.toFixed(1)}</span></div>`).join('')}<p class="help">${Object.entries(a.penalties).map(([k,val])=>`${k}: −${val}`).join(' · ')}</p></section></div><h2>Next bottleneck thesis</h2>${data.themes.filter(t=>c.themes.includes(t.id)).map(thesis).join('')||'<p class="muted">No linked hypothesis</p>'}<section class="panel"><h2>Revenue breakdown / Growth engine / Backlog / Bookings</h2><div class="metric-grid">${Object.keys(metricLabels).slice(18).map(k=>metric(c,k)).join('')}</div><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Period</th><th>Revenue</th><th>YoY</th><th>Gross margin</th></tr></thead><tbody>${(c.quarters||[]).map(q=>`<tr><td>${esc(q.period)}</td><td>${fmt(q.revenue,'USD')}</td><td>${fmt(q.yoy,'%')}</td><td>${fmt(q.grossMargin,'%')}</td></tr>`).join('')||'<tr><td colspan="4">DATA UNAVAILABLE</td></tr>'}</tbody></table></div></section><div class="grid2"><section class="panel"><h2>China risk</h2><p>${badge(a.chinaRisk||'REVIEW REQUIRED','amber')}</p><p class="muted">${esc(a.chinaReason)}</p><p class="help">생산 / 고객 매출 / 허가 / 정책 / 핵심 공급망의 중대한 노출을 함께 검토합니다.</p></section><section class="panel"><h2>Bear case</h2>${notes('bear')}<h3>What would break the thesis</h3>${notes('invalidation')}</section></div><section class="panel"><h2>Evidence ledger</h2>${c.evidence.map(e=>`<div class="evidence"><small>${esc(e.type)} · ${esc(e.date)} · ${e.reviewed?'Reviewed':'Unreviewed'}</small><p>${esc(e.note)}</p>${link(e.source)}</div>`).join('')||'<p class="muted">검증된 증거가 없습니다.</p>'}<h3>Official filings</h3>${(c.filings||[]).map(f=>`<span class="chip">${link(f.source,`${f.form} / ${f.date}`)}</span>`).join('')||na}</section><section class="panel"><h2>Technical chart</h2>${chart(c)}<div class="metric-grid">${Object.entries(c.technical||{}).filter(([k,val])=>typeof val==='number').map(([k,val])=>`<div class="metric"><label>${esc(k)}</label><b>${fmt(val)}</b></div>`).join('')}</div><p class="help">${esc(a.divergence||'펀더멘털·가격 괴리 신호 없음. RSI 단독 판단을 사용하지 않습니다.')}</p></section><section class="panel"><h2>Earnings keyword trend</h2><p class="help">Document mentions / 10,000 words · Narrative shift is a research signal</p>${c.narrative.filter(n=>n.counts.some(x=>x.count)).map(n=>`<div class="source-row"><span>${esc(n.keyword)} <small class="muted">${esc(n.documentKind||'')}</small> ${n.shift?badge('NARRATIVE SHIFT','green'):''}</span><span>${n.counts.map(x=>`${esc(x.period)}: ${x.count} (${x.per10k.toFixed(1)}/10k)`).join(' → ')}</span></div>`).join('')||'<p class="muted">DATA UNAVAILABLE — 원문 문서를 입력하면 추세를 계산합니다.</p>'}</section><section class="panel"><h2>Catalyst calendar</h2>${c.catalysts.map(e=>`<p>${esc(e.eventDate)} · ${esc(e.note)} ${link(e.source)}</p>`).join('')||na}</section><section class="panel"><span class="kicker">THE RE-RATING QUESTION</span><h3>시장이 이 회사를 현재 무엇으로 보고 있는가</h3>${notes('marketPerception')}<h3>실제로 회사에서 무엇이 바뀌고 있는가</h3><p>${v(c,'newProductRevenueGrowth')!=null?`신규 제품 매출 증가율 ${fmt(v(c,'newProductRevenueGrowth'),'%')}`:'검증된 신규 사업 변화 데이터가 없어 판단을 보류합니다.'}</p><h3>시장이 앞으로 재평가할 가능성이 있는 핵심 변수는 무엇인가</h3><p class="muted">신규 성장사업 매출 비중, 수주 전환, 이익률과 현금흐름의 지속성을 확인해야 합니다.</p></section>`;
 if(!$('#detail').open)$('#detail').showModal();bind($('#detailContent'));localize($('#detailContent'));}
function addEvidence(ticker){if(data.mode!=='local'){notice('증거 저장은 로컬 엔진에서 사용할 수 있습니다. 제공된 프로젝트에서 npm start로 실행하세요.');return;}$('#entryForm').reset();$('#entryForm [name=ticker]').innerHTML=data.companies.map(c=>`<option ${c.ticker===ticker?'selected':''}>${c.ticker}</option>`).join('');$('#entryForm [name=date]').value=new Date().toISOString().slice(0,10);$('#entryError').textContent='';localize($('#entry'));$('#entry').showModal();}
function bind(root=$('#app')){localize(root);
 root.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>openCompany(b.dataset.company));
 root.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{const t=data.themes.find(t=>t.id===b.dataset.theme);$('#detailContent').innerHTML=`<div class="dialog-head"><span class="kicker">NEXT BOTTLENECK ENGINE</span><button class="close" data-close="detail">×</button></div>${thesis(t)}<button id="filterFromThesis" class="primary">View related companies</button>`;$('#detail').showModal();bind($('#detailContent'));localize($('#detailContent'));$('#filterFromThesis').onclick=()=>{$('#detail').close();themeFilter=t.id;view='scanner';render();};});
 root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addEvidence(b.dataset.add));
 root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});
 root.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{sortDir=sortKey===b.dataset.sort?-sortDir:-1;sortKey=b.dataset.sort;$('#results').innerHTML=table();bind($('#results'));localize($('#results')); });
 root.querySelectorAll('[data-watch]').forEach(b=>b.onclick=async()=>{const t=b.dataset.watch;watch=watch.includes(t)?watch.filter(x=>x!==t):[...watch,t];try{if(data.mode==='local')await api('watchlist',{tickers:watch});else localStorage.setItem('nbs-watch',JSON.stringify(watch));render();if($('#detail').open)openCompany(t);}catch(e){notice(e.message);}});
 if($('#search'))$('#search').oninput=e=>{query=e.target.value;$('#results').innerHTML=table();bind($('#results'));};if($('#themeFilter'))$('#themeFilter').onchange=e=>{themeFilter=e.target.value;render();};
 if($('#exportCsv'))$('#exportCsv').onclick=()=>download('research-candidates.csv','ticker,company,score,coverage,china_risk,status\n'+filterRows().map(c=>[c.ticker,c.name,c.assessment.score??'DATA UNAVAILABLE',c.assessment.coverage,c.assessment.chinaRisk||'DATA UNAVAILABLE',c.assessment.status].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv');
 if($('#documentForm'))$('#documentForm').onsubmit=async e=>{e.preventDefault();if(data.mode!=='local')return notice('문서 분석은 로컬 엔진에서 실행하세요.');const p=Object.fromEntries(new FormData(e.target));try{await api('document',{ticker:p.ticker,document:p});await load();notice('문서를 저장하고 키워드 추세를 다시 계산했습니다.');}catch(err){notice(err.message);}};
 if($('#companyForm'))$('#companyForm').onsubmit=async e=>{e.preventDefault();if(data.mode!=='local')return notice('종목 추가는 로컬 엔진에서 실행하세요.');try{await api('company',Object.fromEntries(new FormData(e.target)));await load();notice('조사 대상에 추가했습니다. 업데이트 후 자격 조건을 검증합니다.');}catch(err){notice(err.message);}};
}
function download(name,text,type='text/markdown'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function renderReport(){let text;if(data.mode!=='local'&&data.reportText){text=data.reportText;}else if(data.mode==='local'){const r=await fetch('/api/report');text=await r.text();}else{const sections=['오늘 시장 배경','오늘 새롭게 나타난 병목','새로 발견된 기업','기존 후보 업데이트','실적 대비 주가 괴리','밸류에이션 과열 후보','중국 리스크로 제외된 기업','오늘의 Catalyst','차트 상태','오늘 추가로 연구해야 할 기업'];text='US MIDCAP NEXT BOTTLENECK DAILY\n'+data.generatedAt+'\n\n'+sections.map((s,i)=>`${i+1}. ${s}\n${i===0?data.marketContext:i===9?core().map(c=>c.ticker+' · '+c.assessment.status).join('\n')||'검증된 후보가 없어 목록을 채우지 않습니다.':'DATA UNAVAILABLE — 로컬 엔진의 일일 리포트에서 확인하세요.'}`).join('\n\n');}text=text.replaceAll('Research Priority','우선 연구').replaceAll('Thesis Strengthening','논리 강화').replaceAll('Thesis Weakening','논리 약화').replaceAll('Fully Priced','선반영 가능성').replaceAll('Risk Elevated','위험 상승').replaceAll('Watch','관찰').replaceAll('coverage','데이터 충족률').replaceAll('score','점수');if($('#reportBody'))$('#reportBody').textContent=text;if($('#downloadReport'))$('#downloadReport').onclick=()=>download('next-bottleneck-daily.md',text);}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
$('#entryForm').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target)),ev={...p,reviewed:p.reviewed==='on'};if(p.value!=='')ev.value=Number(p.value);try{await api('evidence',{ticker:p.ticker,evidence:ev});$('#entry').close();await load();if($('#detail').open)openCompany(p.ticker);notice('출처와 함께 증거를 저장했습니다.');}catch(err){$('#entryError').textContent=err.message;}};
$('#refresh').onclick=async()=>{if(!data)return;try{if(data.mode==='local'){await api('update',{});notice('수집을 시작했습니다. 완료 시 화면이 갱신됩니다.');$('#refresh').disabled=true;const timer=setInterval(async()=>{try{const s=await api('snapshot');if(!s.updating){clearInterval(timer);$('#refresh').disabled=false;await load();notice('업데이트가 끝났습니다. 누락·실패 내역은 Data & evidence에서 확인하세요.');}}catch{clearInterval(timer);$('#refresh').disabled=false;notice('수집 상태를 확인할 수 없습니다. 다시 불러오세요.');}},5000);}else{await load();notice('저장된 스냅샷을 다시 불러왔습니다. 실시간 수집은 로컬 엔진에서 실행합니다.');}}catch(e){notice(e.message);}};
localize(document.body);try{await load();}catch(e){$('#app').innerHTML='<div class="empty">데이터를 불러올 수 없습니다. 로컬 엔진에서 npm run export를 실행하세요.</div>';notice(e.message);}
if(document.modelContext?.registerTool){for(const tool of [{name:'search_research_companies',description:'Search loaded company research and update the visible table',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(typeof input?.query!=='string')throw Error('query must be string');query=input.query;view='scanner';render();return filterRows().map(c=>({ticker:c.ticker,status:c.assessment.status,score:c.assessment.score}));}},{name:'open_company_research',description:'Open a company evidence detail panel',inputSchema:{type:'object',properties:{ticker:{type:'string'}},required:['ticker'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(typeof input?.ticker!=='string')throw Error('ticker required');openCompany(input.ticker);return {ticker:input.ticker,opened:true};}}])try{await document.modelContext.registerTool(tool);}catch{}}
